SELECT * FROM (SELECT e.event_id, m.case_id, e.activity, e.timestamp FROM (SELECT * FROM (SELECT 'RI:' || i.instruction_id event_id, m.material_id case_id, 'Rolling Instruction Released' activity, i.released_at timestamp FROM rolling_instruction i JOIN as_rolled_material m ON i.instruction_id=m.instruction_id UNION ALL SELECT 'YD:' || tracking_id event_id, material_id case_id, 'Yard Instruction Received' activity, yard_instruction_received_at timestamp FROM furnace_charge_tracking UNION ALL SELECT 'RH:' || material_id event_id, material_id case_id, 'Reheating Started' activity, furnace_charged_at timestamp FROM as_rolled_material WHERE furnace_charged_at IS NOT NULL UNION ALL SELECT 'CS:' || material_id event_id, material_id case_id, 'Crop Shear Passed' activity, crop_shear_passed_at timestamp FROM as_rolled_material WHERE crop_shear_passed_at IS NOT NULL UNION ALL SELECT 'CI:' || instruction_id event_id, material_id case_id, 'Cutting Instruction Released' activity, released_at timestamp FROM cutting_finishing_instruction UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Rolling Completed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='RL' UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Cooling Completed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='CO' UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Leveling Completed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='LE' UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Split Cutting Completed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='SC' UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Heat Treatment Completed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='HT' UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Inspection Failed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='IF' UNION ALL SELECT 'OP:' || h.transaction_id event_id, r.case_id case_id, 'Inspection Passed' activity, h.completed_at timestamp FROM material_operation_history h JOIN (SELECT material_id AS recorded_id, material_id AS case_id FROM as_rolled_material UNION ALL SELECT p.plate_material_id, m.material_id FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no) r ON h.material_id=r.recorded_id WHERE h.operation_code='IP' UNION ALL SELECT 'DIM:' || p.plate_material_id event_id, m.material_id case_id, 'Dimensional Inspection Completed' activity, p.dimension_inspected_at timestamp FROM plate_material p JOIN as_rolled_material m ON p.parent_as_rolled_plate_no=m.as_rolled_plate_no WHERE p.dimension_inspected_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:slab_material:' || slab_id || ':1' event_id, 'Slab Received' activity, slab_received_at timestamp FROM slab_material WHERE slab_received_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:slab_material:' || slab_id || ':2' event_id, 'Slab Identity Verified' activity, slab_identity_verified_at timestamp FROM slab_material WHERE slab_identity_verified_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:slab_material:' || slab_id || ':3' event_id, 'Slab Quality Checked' activity, slab_quality_checked_at timestamp FROM slab_material WHERE slab_quality_checked_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:slab_material:' || slab_id || ':4' event_id, 'Slab Released for Rolling' activity, slab_released_for_rolling_at timestamp FROM slab_material WHERE slab_released_for_rolling_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:planned_rolling_instruction:' || plan_id || ':1' event_id, 'Rolling Plan Created' activity, rolling_plan_created_at timestamp FROM planned_rolling_instruction WHERE rolling_plan_created_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:planned_rolling_instruction:' || plan_id || ':2' event_id, 'Rolling Plan Reviewed' activity, rolling_plan_reviewed_at timestamp FROM planned_rolling_instruction WHERE rolling_plan_reviewed_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:planned_rolling_instruction:' || plan_id || ':3' event_id, 'Rolling Plan Approved' activity, rolling_plan_approved_at timestamp FROM planned_rolling_instruction WHERE rolling_plan_approved_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:planned_rolling_instruction:' || plan_id || ':4' event_id, 'Rolling Plan Released' activity, rolling_plan_released_at timestamp FROM planned_rolling_instruction WHERE rolling_plan_released_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:rolling_instruction:' || instruction_id || ':1' event_id, 'Rolling Instruction Acknowledged' activity, rolling_instruction_acknowledged_at timestamp FROM rolling_instruction WHERE rolling_instruction_acknowledged_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:rolling_instruction:' || instruction_id || ':2' event_id, 'Rolling Setup Verified' activity, rolling_setup_verified_at timestamp FROM rolling_instruction WHERE rolling_setup_verified_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:rolling_instruction:' || instruction_id || ':3' event_id, 'Rolling Work Started' activity, rolling_work_started_at timestamp FROM rolling_instruction WHERE rolling_work_started_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:rolling_instruction:' || instruction_id || ':4' event_id, 'Rolling Instruction Closed' activity, rolling_instruction_closed_at timestamp FROM rolling_instruction WHERE rolling_instruction_closed_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:furnace_charge_tracking:' || tracking_id || ':1' event_id, 'Furnace Charge Assigned' activity, furnace_charge_assigned_at timestamp FROM furnace_charge_tracking WHERE furnace_charge_assigned_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:furnace_charge_tracking:' || tracking_id || ':2' event_id, 'Furnace Charge Confirmed' activity, furnace_charge_confirmed_at timestamp FROM furnace_charge_tracking WHERE furnace_charge_confirmed_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT transaction_id event_id, 'Heating Completed' activity, completed_at timestamp FROM material_operation_history WHERE operation_code='HF') UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:furnace_charge_tracking:' || tracking_id || ':4' event_id, 'Furnace Discharge Confirmed' activity, furnace_discharge_confirmed_at timestamp FROM furnace_charge_tracking WHERE furnace_discharge_confirmed_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:cutting_finishing_instruction:' || instruction_id || ':1' event_id, 'Cutting Instruction Acknowledged' activity, cutting_instruction_acknowledged_at timestamp FROM cutting_finishing_instruction WHERE cutting_instruction_acknowledged_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:cutting_finishing_instruction:' || instruction_id || ':2' event_id, 'Cutting Setup Verified' activity, cutting_setup_verified_at timestamp FROM cutting_finishing_instruction WHERE cutting_setup_verified_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:cutting_finishing_instruction:' || instruction_id || ':3' event_id, 'Cutting Work Started' activity, cutting_work_started_at timestamp FROM cutting_finishing_instruction WHERE cutting_work_started_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:cutting_finishing_instruction:' || instruction_id || ':4' event_id, 'Cutting Instruction Closed' activity, cutting_instruction_closed_at timestamp FROM cutting_finishing_instruction WHERE cutting_instruction_closed_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:plate_material:' || plate_material_id || ':1' event_id, 'Plate Piece Identified' activity, plate_piece_identified_at timestamp FROM plate_material WHERE plate_piece_identified_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT transaction_id event_id, 'Plate Surface Checked' activity, completed_at timestamp FROM material_operation_history WHERE operation_code='SF') UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:plate_material:' || plate_material_id || ':3' event_id, 'Plate Quality Released' activity, plate_quality_released_at timestamp FROM plate_material WHERE plate_quality_released_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:plate_material:' || plate_material_id || ':4' event_id, 'Plate Packed' activity, plate_packed_at timestamp FROM plate_material WHERE plate_packed_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:plate_material:' || plate_material_id || ':5' event_id, 'Plate Quality Review Started' activity, plate_quality_review_started_at timestamp FROM plate_material WHERE plate_quality_review_started_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:plate_material:' || plate_material_id || ':6' event_id, 'Plate Packing Started' activity, plate_packing_started_at timestamp FROM plate_material WHERE plate_packing_started_at IS NOT NULL)) e JOIN (SELECT 'RI:' || instruction_id event_id, plan_id case_id FROM rolling_instruction UNION ALL SELECT e.event_id,o.plan_id case_id FROM (SELECT 'LC:planned_rolling_instruction:' || plan_id || ':1' event_id, 'Rolling Plan Created' activity, rolling_plan_created_at timestamp FROM planned_rolling_instruction WHERE rolling_plan_created_at IS NOT NULL) e JOIN planned_rolling_instruction o ON e.event_id='LC:planned_rolling_instruction:' || o.plan_id || ':1' UNION ALL SELECT e.event_id,o.plan_id case_id FROM (SELECT 'LC:planned_rolling_instruction:' || plan_id || ':2' event_id, 'Rolling Plan Reviewed' activity, rolling_plan_reviewed_at timestamp FROM planned_rolling_instruction WHERE rolling_plan_reviewed_at IS NOT NULL) e JOIN planned_rolling_instruction o ON e.event_id='LC:planned_rolling_instruction:' || o.plan_id || ':2' UNION ALL SELECT e.event_id,o.plan_id case_id FROM (SELECT 'LC:planned_rolling_instruction:' || plan_id || ':3' event_id, 'Rolling Plan Approved' activity, rolling_plan_approved_at timestamp FROM planned_rolling_instruction WHERE rolling_plan_approved_at IS NOT NULL) e JOIN planned_rolling_instruction o ON e.event_id='LC:planned_rolling_instruction:' || o.plan_id || ':3' UNION ALL SELECT e.event_id,o.plan_id case_id FROM (SELECT 'LC:planned_rolling_instruction:' || plan_id || ':4' event_id, 'Rolling Plan Released' activity, rolling_plan_released_at timestamp FROM planned_rolling_instruction WHERE rolling_plan_released_at IS NOT NULL) e JOIN planned_rolling_instruction o ON e.event_id='LC:planned_rolling_instruction:' || o.plan_id || ':4') m ON m.event_id=e.event_id ORDER BY m.case_id,e.timestamp,e.event_id) WHERE activity IN ('Rolling Instruction Released','Rolling Plan Approved','Rolling Plan Created') ORDER BY case_id,timestamp,event_id;
